  const handleDownloadPDF = async (pdfIdOrCompress: string | boolean, pdfUrlInput?: string, defaultNameInput?: string) => {
    setDownloadProgress(0);
    setDownloadStatus("جاري الاتصال وسحب الملف الأصلي...");
    
    let pdfId = "tahdedat";
    let pdfUrl = "/tahdedat_pediatrics.pdf";
    let defaultName = "تحديدات_الأطفال.pdf";
    
    if (typeof pdfIdOrCompress === 'boolean') {
      const compressFlag = pdfIdOrCompress;
      pdfUrl = compressFlag ? "/tahdedat_pediatrics_compressed.pdf" : "/tahdedat_pediatrics.pdf";
      defaultName = compressFlag ? "تحديدات_الأطفال_مضغوط.pdf" : "تحديدات_الأطفال.pdf";
      pdfId = "tahdedat";
    } else {
      pdfId = pdfIdOrCompress;
      pdfUrl = pdfUrlInput || "";
      defaultName = defaultNameInput || "document.pdf";
    }
    
    const rawDisplayName = user?.displayName || userData?.name || user?.email?.split('@')[0] || "User";
    const displayEmail = user?.email || userData?.email || "user@gmail.com";
    const cleanDisplayName = rawDisplayName.replace(/[^\x00-\x7F]/g, "").trim() || displayEmail.split('@')[0];
    
    try {
      // Step 1: Fetch PDF bytes
      const response = await fetch(pdfUrl);
      if (!response.ok) throw new Error("Failed to load PDF template file.");
      
      const contentLength = response.headers.get("content-length");
      const totalBytes = contentLength ? parseInt(contentLength, 10) : 0;
      
      const reader = response.body?.getReader();
      if (!reader) throw new Error("Failed to initialize PDF stream reader.");
      
      let receivedBytes = 0;
      const chunks: Uint8Array[] = [];
      
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        
        chunks.push(value);
        receivedBytes += value.length;
        
        if (totalBytes > 0) {
          const percent = Math.round((receivedBytes / totalBytes) * 70); // Up to 70% for fetching
          setDownloadProgress(percent);
          setDownloadStatus(`جاري تحميل عناصر التجميعة الطبية... ${percent}%`);
        }
      }
      
      setDownloadProgress(75);
      setDownloadStatus("جاري تهيئة وتوقيع ملف الـ PDF مائياً في المتصفح...");
      
      // Step 2: Combine chunks
      const pdfBytes = new Uint8Array(receivedBytes);
      let offset = 0;
      for (const chunk of chunks) {
        pdfBytes.set(chunk, offset);
        offset += chunk.length;
      }
      
      // Step 3: Load pdf-lib dynamically from CDN (highly optimized ESM)
      // @ts-ignore
      const { PDFDocument, rgb, StandardFonts } = await import('https://unpkg.com/pdf-lib@1.17.1/dist/pdf-lib.esm.js');
      
      const pdfDoc = await PDFDocument.load(pdfBytes);
      const helveticaFont = await pdfDoc.embedFont(StandardFonts.Helvetica);
      const helveticaBoldFont = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
      
      setDownloadProgress(85);
      setDownloadStatus("جاري كتابة وتشفير هويتك الرقمية كعلامة مائية أمنية...");
      
      // Page numbers of chapter covers to skip watermarking
      let chapterCovers: number[] = [];
      let margin = 12;
      let box_w = 200;
      let box_h = 13;
      
      if (pdfId === 'questions' || pdfId === 'answers') {
        chapterCovers = [2, 5, 8, 13];
        margin = 20;
        box_w = 170;
        box_h = 14;
      } else if (pdfId === 'quiz' || pdfId === 'quiz_answers') {
        chapterCovers = [];
        margin = 20;
        box_w = 170;
        box_h = 14;
      } else if (pdfId === 'camp2_quiz' || pdfId === 'camp2_quiz_answers' || pdfId === 'camp2_quiz_day2' || pdfId === 'camp2_quiz_day2_answers' || pdfId === 'camp2_essay' || pdfId === 'camp2_essay_answers' || pdfId === 'camp2_essay_day2' || pdfId === 'camp2_essay_day2_answers') {
        chapterCovers = [];
        margin = 15;
        box_w = 170;
        box_h = 14;
      } else if (pdfId.startsWith('second_paper')) {
        if (pdfId.includes('ped')) {
          chapterCovers = [3, 15, 23, 30];
        } else {
          chapterCovers = [3, 15, 23, 30, 36];
        }
        margin = 30;
        box_w = 170;
        box_h = 13;
      } else {
        chapterCovers = [3, 7, 11, 15, 19, 24, 35, 43];
        margin = 12;
        box_w = 200;
        box_h = 13;
      }
      
      const pageCount = pdfDoc.getPageCount();
      
      for (let i = 0; i < pageCount; i++) {
        const p = i + 1;
        // Skip cover, index, and chapter covers
        const skipThreshold = (pdfId === 'camp2_quiz' || pdfId === 'camp2_quiz_answers' || pdfId === 'camp2_quiz_day2' || pdfId === 'camp2_quiz_day2_answers' || pdfId === 'camp2_essay' || pdfId === 'camp2_essay_answers' || pdfId === 'camp2_essay_day2' || pdfId === 'camp2_essay_day2_answers') ? 0 : (pdfId === 'questions' || pdfId === 'answers' || pdfId === 'quiz' || pdfId === 'quiz_answers') ? 1 : 2;
        if (p > skipThreshold && !chapterCovers.includes(p)) {
          const page = pdfDoc.getPage(i);
          const height = page.getHeight();
          const width = page.getWidth();
          
          if (pdfId.startsWith('second_paper')) {
            const header_y = height - 31;
            
            // Clear previous name text area (x: width - 30 - 2*box_w + 22, width: box_w - 24, height: box_h - 2)
            page.drawRectangle({
              x: width - 30 - (2 * box_w) + 22,
              y: header_y + 1.5,
              width: box_w - 24,
              height: box_h - 3,
              color: rgb(248/255, 250/255, 252/255),
              opacity: 1
            });
            
            // Clear previous email text area (x: width - 30 - box_w + 36, width: box_w - 38, height: box_h - 2)
            page.drawRectangle({
              x: width - 30 - box_w + 36,
              y: header_y + 1.5,
              width: box_w - 38,
              height: box_h - 3,
              color: rgb(248/255, 250/255, 252/255),
              opacity: 1
            });
            
            page.drawText(cleanDisplayName, {
              x: width - 30 - (2 * box_w) + 25,
              y: header_y + 3.5,
              size: 6.5,
              font: helveticaFont,
              color: rgb(15/255, 23/255, 42/255),
            });
            
            page.drawText(displayEmail, {
              x: width - 30 - box_w + 38,
              y: header_y + 3.5,
              size: 6.5,
              font: helveticaFont,
              color: rgb(15/255, 23/255, 42/255),
            });
          } else {
            const header_y = height - margin - (pdfId === 'questions' || pdfId === 'answers' || pdfId === 'quiz' || pdfId === 'quiz_answers' ? 22 : 17);
            
            if (pdfId === 'questions' || pdfId === 'answers' || pdfId === 'quiz' || pdfId === 'quiz_answers') {
              // Clear placeholders
              page.drawRectangle({
                x: margin + 40,
                y: header_y + 1.5,
                width: box_w - 42,
                height: box_h - 3,
                color: rgb(240/255, 249/255, 255/255),
                opacity: 1
              });
              page.drawRectangle({
                x: width - margin - box_w + 42,
                y: header_y + 1.5,
                width: box_w - 44,
                height: box_h - 3,
                color: rgb(240/255, 249/255, 255/255),
                opacity: 1
              });
            } else {
              // Draw left box
              page.drawRectangle({
                x: margin + 5,
                y: header_y,
                width: box_w,
                height: box_h,
                color: rgb(240/255, 249/255, 255/255),
                borderColor: rgb(186/255, 230/255, 253/255),
                borderWidth: 0.5,
                opacity: 1,
              });
              
              // Draw right box
              page.drawRectangle({
                x: width - margin - box_w - 5,
                y: header_y,
                width: box_w,
                height: box_h,
                color: rgb(240/255, 249/255, 255/255),
                borderColor: rgb(186/255, 230/255, 253/255),
                borderWidth: 0.5,
                opacity: 1,
              });
              
              page.drawText('USER:', {
                x: margin + 10,
                y: header_y + 3.5,
                size: 7,
                font: helveticaBoldFont,
                color: rgb(3/255, 105/255, 161/255),
              });
              page.drawText('EMAIL:', {
                x: width - margin - box_w + 10,
                y: header_y + 3.5,
                size: 7,
                font: helveticaBoldFont,
                color: rgb(3/255, 105/255, 161/255),
              });
            }
            
            page.drawText(cleanDisplayName, {
              x: margin + 42,
              y: header_y + 3.5,
              size: 7,
              font: helveticaFont,
              color: rgb(15/255, 23/255, 42/255),
            });
            
            page.drawText(displayEmail, {
              x: width - margin - box_w + 45,
              y: header_y + 3.5,
              size: 7,
              font: helveticaFont,
              color: rgb(15/255, 23/255, 42/255),
            });
          }
        }
      }
      
      setDownloadProgress(95);
      setDownloadStatus("جاري حفظ مستند التجميعة المشفر...");
      
      const modifiedPdfBytes = await pdfDoc.save();
      
      // Step 4: Trigger native browser download
      const blob = new Blob([modifiedPdfBytes], { type: "application/pdf" });
      const downloadUrl = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = downloadUrl;
      link.download = defaultName;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(downloadUrl);
      
      setDownloadProgress(100);
      setDownloadStatus("تم التنزيل بنجاح! 🎉");
      setTimeout(() => {
        setIsDownloadModalOpen(false);
        setDownloadStatus(null);
      }, 1000);
    } catch (err: any) {
      console.error(err);
      alert(`فشل تجهيز وتنزيل الملف: ${err.message}`);
      setDownloadStatus(null);
    }
  };

