                  const isAdmin          = userData?.role === 'admin';
                  const showUnsolvedEssay = nowMs >= CAMP2_DAY2_START_TIME || isAdmin;
                  const showSolvedEssay   = nowMs >= CAMP2_DAY2_START_TIME || isAdmin;

